package dev.prism.core.document.internal;

import java.io.IOException;
import java.nio.file.Path;

/** Storage for document bytes. Keys are opaque and generated by Prism, never taken from users. */
interface DocumentStore {

    void put(String key, Path source) throws IOException;

    /** Returns a local path to read from. Callers must treat it as read-only. */
    Path locate(String key) throws IOException;

    void delete(String key) throws IOException;
}
